#!/bin/bash
echo "[*] Starting rootkit cleanup and recovery..."

# Step 1: Remove LD_PRELOAD rootkits
echo "[*] Removing LD_PRELOAD hooks..."
sudo rm -f /etc/ld.so.preload
sudo rm -f /usr/local/lib/libprocesshide.so
